SET NOCOUNT ON
GO

USE [master]
GO

DROP DATABASE IF EXISTS [Music_01]
GO

CREATE DATABASE [Music_01]
GO

USE [Music_01]
GO

CREATE TABLE [dbo].[Album](
	[Album_ID] [int] IDENTITY(1,1) NOT NULL PRIMARY KEY,
	[Title] [nvarchar](500) NULL,
	[Artist_ID] [int] NULL,
	[Release_date] [date] NULL,
	[Album_mins] [smallint] NULL,
	[Album_secs] [smallint] NULL,
	[Tracks] [smallint] NULL,
	[Subgenre_ID] [int] NULL,
	[Record_label_ID] [int] NULL,
	[Album_type_ID] [int] NULL,
	[US_Billboard_200_peak] [tinyint] NULL,
	[US_Billboard_200_year_end] [tinyint] NULL,
	[US_sales_(m)] [float] NULL,
	[Wiki_URL] [nvarchar](500) NULL,
	[Cover_art] [nvarchar](500) NULL
)
GO

CREATE TABLE [dbo].[Album_Type](
	[Album_type_ID] [int] IDENTITY(1,1) NOT NULL PRIMARY KEY,
	[Album_type] [nvarchar](255) NULL
)
GO

CREATE TABLE [dbo].[Artist](
	[Artist_ID] [int] IDENTITY(1,1) NOT NULL PRIMARY KEY,
	[Artist] [nvarchar](255) NULL,
	[Artist_type] [nvarchar](255) NULL,
	[Year_formed] [smallint] NULL,
	[Year_disbanded] [smallint] NULL
)
GO

CREATE TABLE [dbo].[City](
	[City_ID] [int] IDENTITY(1,1) NOT NULL PRIMARY KEY,
	[City] [nvarchar](255) NULL,
	[Country_ID] [int] NULL
)
GO

CREATE TABLE [dbo].[Continent](
	[Continent_ID] [int] IDENTITY(1,1) NOT NULL PRIMARY KEY,
	[Continent] [nvarchar](255) NULL
)
GO

CREATE TABLE [dbo].[Country](
	[Country_ID] [int] IDENTITY(1,1) NOT NULL PRIMARY KEY,
	[Country] [nvarchar](255) NULL,
	[Continent_ID] [int] NULL,
	[Flag_URL] [nvarchar](500) NULL
)
GO

CREATE TABLE [dbo].[Genre](
	[Genre_ID] [int] IDENTITY(1,1) NOT NULL PRIMARY KEY,
	[Genre] [nvarchar](255) NULL
)
GO

CREATE TABLE [dbo].[Parent_Company](
	[Parent_company_ID] [int] IDENTITY(1,1) NOT NULL PRIMARY KEY,
	[Parent_company] [nvarchar](255) NULL,
	[Logo_URL] [nvarchar](500) NULL
)
GO

CREATE TABLE [dbo].[Record_Label](
	[Record_label_ID] [int] IDENTITY(1,1) NOT NULL PRIMARY KEY,
	[Record_label] [nvarchar](255) NULL,
	[Parent_company_ID] [int] NULL,
	[Logo_URL] [nvarchar](500) NULL
)
GO

CREATE TABLE [dbo].[Show](
	[Show_ID] [int] IDENTITY(1,1) NOT NULL PRIMARY KEY,
	[Tour_ID] [int] NULL,
	[Leg] [nvarchar](255) NULL,
	[Show_date] [date] NULL,
	[Venue_ID] [int] NULL,
	[Tickets_sold] [int] NULL,
	[Tickets_available] [int] NULL,
	[Revenue_$] [bigint] NULL,
	[Cancelled] [bit] NULL,
	[Cancellation_reason] [nvarchar](500) NULL
)
GO

CREATE TABLE [dbo].[Subgenre](
	[Subgenre_ID] [int] IDENTITY(1,1) NOT NULL PRIMARY KEY,
	[Subgenre] [nvarchar](255) NULL,
	[Genre_ID] [int] NULL
)
GO

CREATE TABLE [dbo].[Tour](
	[Tour_ID] [int] IDENTITY(1,1) NOT NULL PRIMARY KEY,
	[Artist_ID] [int] NULL,
	[Tour_name] [nvarchar](500) NULL,
	[Start_date] [date] NULL,
	[End_date] [date] NULL,
	[Legs] [tinyint] NULL,
	[Shows] [smallint] NULL,
	[Attendance] [bigint] NULL,
	[Tour_gross_$] [bigint] NULL,
	[Album_ID] [int] NULL
)
GO

CREATE TABLE [dbo].[Track](
	[Track_ID] [int] IDENTITY(1,1) NOT NULL PRIMARY KEY,
	[Album_ID] [int] NULL,
	[Track_order] [smallint] NULL,
	[Track_name] [nvarchar](1000) NULL,
	[Track_mins] [smallint] NULL,
	[Track_secs] [smallint] NULL,
	[Single_release_date] [date] NULL,
	[US_Billboard_Hot_100_peak] [tinyint] NULL,
	[US_Billboard_Hot_100_year_end] [tinyint] NULL,
	[US_sales_(m)] [float] NULL
)
GO

CREATE TABLE [dbo].[Venue](
	[Venue_ID] [int] IDENTITY(1,1) NOT NULL PRIMARY KEY,
	[Venue] [nvarchar](500) NULL,
	[Venue_type_ID] [int] NULL,
	[Capacity] [int] NULL,
	[Construction_start_date] [date] NULL,
	[Opening_date] [date] NULL,
	[Closing_date] [date] NULL,
	[Demolition_date] [date] NULL,
	[Construction_cost_$m] [float] NULL,
	[Address] [nvarchar](1000) NULL,
	[City_ID] [int] NULL,
	[Latitude] [float] NULL,
	[Longitude] [float] NULL,
	[Other_names] [nvarchar](4000) NULL
)
GO

CREATE TABLE [dbo].[Venue_Category](
	[Venue_category_ID] [int] IDENTITY(1,1) NOT NULL PRIMARY KEY,
	[Venue_category] [nvarchar](255) NULL
)
GO

CREATE TABLE [dbo].[Venue_Type](
	[Venue_type_ID] [int] IDENTITY(1,1) NOT NULL PRIMARY KEY,
	[Venue_type] [nvarchar](255) NULL,
	[Venue_category_ID] [int] NULL
)
GO

SET IDENTITY_INSERT [dbo].[Album] ON 
GO
